package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.IngestKeyVO;

class IngestKeyValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of ingest key of observed source")
  void test_ingest_key_value_holder_assign_plain_value() {
    Object holder = new Object();
    IngestKeyValueHolder<Object> value = new IngestKeyValueHolder<>(holder);
    Assertions.assertSame(holder, value.ingestKey("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getIngestKeyValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getIngestKey().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.ingestKeyNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getIngestKeyValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getIngestKey().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of ingest key of observed source")
  void test_ingest_key_value_holder_assign_value_object() {
    Object holder = new Object();
    IngestKeyValueHolder<Object> value = new IngestKeyValueHolder<>(holder);
    IngestKeyVO vo = IngestKeyVO.from("one");
    Assertions.assertFalse(value.getIngestKeyValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.ingestKey(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getIngestKeyValue().orElseThrow());
    Assertions.assertSame(holder, value.ingestKey(Optional.empty()));
    Assertions.assertFalse(value.getIngestKeyValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.ingestKey(Optional.of(vo)));
    Assertions.assertSame(vo, value.getIngestKeyValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of ingest key of observed source against the original")
  void test_ingest_key_value_holder_read() {
    Object holder = new Object();
    IngestKeyValueHolder<Object> value = new IngestKeyValueHolder<>(holder);
    IngestKeyVO vo = IngestKeyVO.from("one");
    IngestKeyVO other = IngestKeyVO.from("one");
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getIngestKeyValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readIngestKey(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readIngestKey(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.ingestKey(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readIngestKey(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readIngestKey(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of ingest key of observed source")
  void test_ingest_key_value_holder_unset() {
    Object holder = new Object();
    IngestKeyValueHolder<Object> value = new IngestKeyValueHolder<>(holder);
    IngestKeyVO vo = IngestKeyVO.from("one");
    value.ingestKey(vo);
    Assertions.assertSame(holder, value.unsetIngestKeyIfMatches("ingestKey_other"));
    Assertions.assertTrue(value.getIngestKeyValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetIngestKeyIfMatches("ingestKey"));
    Assertions.assertFalse(value.getIngestKeyValue().isPresent(),
        "The field name must clear the value");
    value.ingestKey(vo);
    Assertions.assertSame(holder, value.unsetIngestKey());
    Assertions.assertFalse(value.getIngestKeyValue().isPresent(), "Unset must clear the value");
  }
}
